                self.peerRole = try container.decode(PeerRole?.self, forKey: .peerRole)
                self.peerAccess = try container.decode(String.self, forKey: .peerAccess)
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(self.vaultID, forKey: .vaultID)
                try container.encode(self.switchID, forKey: .switchID)
                try container.encode(self.outcome, forKey: .outcome)
                try container.encode(self.role, forKey: .role)
                try container.encode(self.roleTerm, forKey: .roleTerm)
                try container.encode(self.side, forKey: .side)
                try container.encode(self.phase, forKey: .phase)
                try container.encode(self.term, forKey: .term)
                try container.encode(self.seq, forKey: .seq)
                try container.encode(self.digest, forKey: .digest)
                try container.encode(self.entries, forKey: .entries)
                try container.encode(self.told, forKey: .told)
                try container.encode(self.askedOn, forKey: .askedOn)
                try container.encode(self.askedBy, forKey: .askedBy)
                try container.encode(self.reason, forKey: .reason)
                try container.encode(self.detail, forKey: .detail)
                try container.encode(self.deadline, forKey: .deadline)
                try container.encode(self.createdAt, forKey: .createdAt)
                try container.encode(self.endedAt, forKey: .endedAt)
                try container.encode(self.peerRole, forKey: .peerRole)
                try container.encode(self.peerAccess, forKey: .peerAccess)
            }

            /// Known values (the member stays a String: a newer daemon may send others).
            public enum Outcome {
                public static let switched = "switched"
                public static let abandoned = "abandoned"
                public static let running = "running"
                public static let allValues: [String] = [switched, abandoned, running]
            }

            /// Known values (the member stays a String: a newer daemon may send others).
            public enum Side {
                public static let core = "core"
                public static let mirror = "mirror"
