            }

            /// Known values (the member stays a String: a newer daemon may send others).
            public enum Phase {
                public static let requested = "requested"
                public static let draining = "draining"
                public static let preparing = "preparing"
                public static let prepared = "prepared"
                public static let switched = "switched"
                public static let abandoned = "abandoned"
                public static let allValues: [String] = [requested, draining, preparing, prepared, switched, abandoned]
            }

            /// Known values (the member stays a String: a newer daemon may send others).
            public enum AskedOn {
                public static let core = "core"
                public static let mirror = "mirror"
                public static let allValues: [String] = [core, mirror]
            }

            public struct AskedBy: Codable, Hashable, Sendable {
                public var node: String
                /// Minimum 0.
                public var id: Int64
                public var name: String

                public init(node: String, id: Int64, name: String) {
                    self.node = node
                    self.id = id
                    self.name = name
                }

                enum CodingKeys: String, CodingKey {
                    case node
                    case id
                    case name
                }
            }

            public struct PeerRole: Codable, Hashable, Sendable {
                /// 1-50 characters: the role's name on the core, never matched to a role here.
                public var roleName: String
                /// Minimum 0.
                public var files: Int64
                /// Minimum 0.
                public var directories: Int64
                /// Minimum 0.
                public var sync: Int64
                /// Minimum 0.
                public var roles: Int64

                public init(roleName: String, files: Int64, directories: Int64, sync: Int64, roles: Int64) {
                    self.roleName = roleName
                    self.files = files
                    self.directories = directories
                    self.sync = sync
                    self.roles = roles
                }

                enum CodingKeys: String, CodingKey {
                    case roleName = "role_name"
                    case files
                    case directories
                    case sync
                    case roles
                }
            }

            /// Known values (the member stays a String: a newer daemon may send others).
            public enum PeerAccess {
                public static let readOnly = "read-only"
                public static let readWrite = "read-write"
                public static let none = "none"
                public static let allValues: [String] = [readOnly, readWrite, none]
            }
        }
    }
}

extension Ws.Mirror {
    /// On a mirror whose core is gone or cannot be reached: take over as the vault's core. This server records the next
    /// term with itself as the core, the last change it applied from the old core as the fork point and its tree as the
    /// old core last confirmed it as the fork base (kept for the old core's return); changes made here and still
    /// pending become ordinary changes, held ones stay listed. Refused while the core answers (mirror_core_reachable:
    /// use mirror.switch). Also the way out of a planned switch whose core never came back. `confirm` is the vault's
    /// name, typed. Super admins, or holders of admin.mirror.takeover (Take over as core); the data.destroy step-up in
    /// the console; audited mirror.takeover.
    public enum Takeover: WsRequest {
        public static let command = WsCommand.mirrorTakeover

        public struct Payload: Codable, Hashable, Sendable {
            /// Vault id. Minimum 0.
            public var vaultID: Int64
            /// The vault's name, typed exactly.
            public var confirm: String

            public init(vaultID: Int64, confirm: String) {
                self.vaultID = vaultID
                self.confirm = confirm
            }

            enum CodingKeys: String, CodingKey {
                case vaultID = "vault_id"
                case confirm
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            /// Minimum 0.
            public var id: Int64
            /// Minimum 0.
            public var vaultID: Int64
            /// The old core. Minimum 0.
            public var peerID: Int64
            /// Minimum 0.
            public var fromTerm: Int64
            /// This server's term as the core. Minimum 0.
            public var term: Int64
            /// The fork point: the last change applied from the old core, and the digest there.
            public var fork: Fork
            /// Entries in the fork base. Minimum 0.
            public var forkRows: Int64
            /// Minimum 0.
            public var pendingMadeLocal: Int64
            /// Minimum 0.
            public var held: Int64
            /// Files whose contents never arrived here. Minimum 0.
            public var contentsMissing: Int64
            public var by: By
            /// Minimum 0.
            public var createdAt: Int64
            /// Always sent; nil is null.
            public var settledAt: Int64?
            /// Always sent; nil is null.
            public var settledHow: String?
            /// The fork base's own digest and whether it is the fork point's. An object the contract leaves open (no
            /// fields, model or value shape), kept as JSONObject.
            public var detail: JSONObject
            public var warning: String
            public var forkBaseMatches: Bool

            public init(id: Int64, vaultID: Int64, peerID: Int64, fromTerm: Int64, term: Int64, fork: Fork,
                        forkRows: Int64, pendingMadeLocal: Int64, held: Int64, contentsMissing: Int64, by: By,
                        createdAt: Int64, settledAt: Int64? = nil, settledHow: String? = nil, detail: JSONObject,
                        warning: String, forkBaseMatches: Bool) {
                self.id = id
                self.vaultID = vaultID
                self.peerID = peerID
                self.fromTerm = fromTerm
                self.term = term
                self.fork = fork
                self.forkRows = forkRows
                self.pendingMadeLocal = pendingMadeLocal
                self.held = held
                self.contentsMissing = contentsMissing
                self.by = by
                self.createdAt = createdAt
                self.settledAt = settledAt
                self.settledHow = settledHow
                self.detail = detail
                self.warning = warning
                self.forkBaseMatches = forkBaseMatches
            }

            enum CodingKeys: String, CodingKey {
                case id
                case vaultID = "vault_id"
                case peerID = "peer_id"
                case fromTerm = "from_term"
                case term
                case fork
                case forkRows = "fork_rows"
                case pendingMadeLocal = "pending_made_local"
                case held
                case contentsMissing = "contents_missing"
                case by
                case createdAt = "created_at"
                case settledAt = "settled_at"
                case settledHow = "settled_how"
                case detail
                case warning
                case forkBaseMatches = "fork_base_matches"
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.id = try container.decode(Int64.self, forKey: .id)
                self.vaultID = try container.decode(Int64.self, forKey: .vaultID)
                self.peerID = try container.decode(Int64.self, forKey: .peerID)
                self.fromTerm = try container.decode(Int64.self, forKey: .fromTerm)
                self.term = try container.decode(Int64.self, forKey: .term)
                self.fork = try container.decode(Fork.self, forKey: .fork)
                self.forkRows = try container.decode(Int64.self, forKey: .forkRows)
                self.pendingMadeLocal = try container.decode(Int64.self, forKey: .pendingMadeLocal)
                self.held = try container.decode(Int64.self, forKey: .held)
                self.contentsMissing = try container.decode(Int64.self, forKey: .contentsMissing)
                self.by = try container.decode(By.self, forKey: .by)
                self.createdAt = try container.decode(Int64.self, forKey: .createdAt)
                self.settledAt = try container.decode(Int64?.self, forKey: .settledAt)
                self.settledHow = try container.decode(String?.self, forKey: .settledHow)
                self.detail = try container.decode(JSONObject.self, forKey: .detail)
                self.warning = try container.decode(String.self, forKey: .warning)
                self.forkBaseMatches = try container.decode(Bool.self, forKey: .forkBaseMatches)
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(self.id, forKey: .id)
                try container.encode(self.vaultID, forKey: .vaultID)
                try container.encode(self.peerID, forKey: .peerID)
                try container.encode(self.fromTerm, forKey: .fromTerm)
                try container.encode(self.term, forKey: .term)
                try container.encode(self.fork, forKey: .fork)
                try container.encode(self.forkRows, forKey: .forkRows)
                try container.encode(self.pendingMadeLocal, forKey: .pendingMadeLocal)
                try container.encode(self.held, forKey: .held)
                try container.encode(self.contentsMissing, forKey: .contentsMissing)
                try container.encode(self.by, forKey: .by)
                try container.encode(self.createdAt, forKey: .createdAt)
                try container.encode(self.settledAt, forKey: .settledAt)
                try container.encode(self.settledHow, forKey: .settledHow)
                try container.encode(self.detail, forKey: .detail)
                try container.encode(self.warning, forKey: .warning)
                try container.encode(self.forkBaseMatches, forKey: .forkBaseMatches)
            }

            public struct Fork: Codable, Hashable, Sendable {
                /// Minimum 0.
                public var term: Int64
                /// Minimum 0.
                public var seq: Int64
                public var digest: String
                public var entries: Int64

                public init(term: Int64, seq: Int64, digest: String, entries: Int64) {
                    self.term = term
                    self.seq = seq
                    self.digest = digest
                    self.entries = entries
                }

                enum CodingKeys: String, CodingKey {
                    case term
                    case seq
                    case digest
                    case entries
                }
            }

            public struct By: Codable, Hashable, Sendable {
                /// Always sent; nil is null.
                public var id: Int64?
                public var name: String

                public init(id: Int64? = nil, name: String) {
                    self.id = id
                    self.name = name
                }

                enum CodingKeys: String, CodingKey {
                    case id
                    case name
                }

                public init(from decoder: any Decoder) throws {
                    let container = try decoder.container(keyedBy: CodingKeys.self)
                    self.id = try container.decode(Int64?.self, forKey: .id)
                    self.name = try container.decode(String.self, forKey: .name)
                }

                public func encode(to encoder: any Encoder) throws {
                    var container = encoder.container(keyedBy: CodingKeys.self)
                    try container.encode(self.id, forKey: .id)
                    try container.encode(self.name, forKey: .name)
                }
            }
        }
    }
}

extension Ws.Mirror.Versions {
    /// Keep versions of what the core replaces or deletes, for a vault this server holds as another server's mirror
    /// (default off): before the core's replacement, trash or delete of a file is applied here, its prior generation is
    /// kept as a local version, bounded by keep_last, max_age_days and quota_bytes (unset ones default to 10 versions
    /// and 30 days when turning it on; 0 is no limit of that kind; at least one stays). This server's own state: never
    /// logged, hashed or submitted. Read them with recovery.list|inspect (whoever may read the file here); restoring
    /// one is a change made here (Live only). Super admins; audited mirror.versions.set.
    public enum Set: WsRequest {
        public static let command = WsCommand.mirrorVersionsSet

        public struct Payload: Codable, Hashable, Sendable {
            /// Vault id. Minimum 0.
            public var vaultID: Int64
            public var enabled: Bool
            /// Minimum 0. nil omits it, `.null` sends null.
            public var keepLast: Nullable<Int64>?
            /// Minimum 0. nil omits it, `.null` sends null.
            public var maxAgeDays: Nullable<Int64>?
            /// Minimum 0. nil omits it, `.null` sends null.
            public var quotaBytes: Nullable<Int64>?

            public init(vaultID: Int64, enabled: Bool, keepLast: Nullable<Int64>? = nil,
                        maxAgeDays: Nullable<Int64>? = nil, quotaBytes: Nullable<Int64>? = nil) {
                self.vaultID = vaultID
                self.enabled = enabled
                self.keepLast = keepLast
                self.maxAgeDays = maxAgeDays
                self.quotaBytes = quotaBytes
            }

            enum CodingKeys: String, CodingKey {
                case vaultID = "vault_id"
                case enabled
                case keepLast = "keep_last"
                case maxAgeDays = "max_age_days"
                case quotaBytes = "quota_bytes"
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.vaultID = try container.decode(Int64.self, forKey: .vaultID)
                self.enabled = try container.decode(Bool.self, forKey: .enabled)
                self.keepLast = container.contains(.keepLast)
                    ? try container.decode(Nullable<Int64>.self, forKey: .keepLast) : nil
                self.maxAgeDays = container.contains(.maxAgeDays)
                    ? try container.decode(Nullable<Int64>.self, forKey: .maxAgeDays) : nil
                self.quotaBytes = container.contains(.quotaBytes)
                    ? try container.decode(Nullable<Int64>.self, forKey: .quotaBytes) : nil
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(self.vaultID, forKey: .vaultID)
                try container.encode(self.enabled, forKey: .enabled)
                try container.encodeIfPresent(self.keepLast, forKey: .keepLast)
                try container.encodeIfPresent(self.maxAgeDays, forKey: .maxAgeDays)
                try container.encodeIfPresent(self.quotaBytes, forKey: .quotaBytes)
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var versions: Versions

            public init(versions: Versions) {
                self.versions = versions
            }

            enum CodingKeys: String, CodingKey {
                case versions
            }

            public struct Versions: Codable, Hashable, Sendable {
                public var enabled: Bool
                /// Always sent; nil is null.
                public var keepLast: Int64?
                /// Always sent; nil is null.
                public var maxAgeDays: Int64?
                /// Always sent; nil is null.
                public var quotaBytes: Int64?
                /// Always sent; nil is null.
                public var setBy: Int64?
                /// Always sent; nil is null.
                public var setAt: Int64?

                public init(enabled: Bool, keepLast: Int64? = nil, maxAgeDays: Int64? = nil, quotaBytes: Int64? = nil,
                            setBy: Int64? = nil, setAt: Int64? = nil) {
                    self.enabled = enabled
                    self.keepLast = keepLast
                    self.maxAgeDays = maxAgeDays
                    self.quotaBytes = quotaBytes
                    self.setBy = setBy
                    self.setAt = setAt
                }

                enum CodingKeys: String, CodingKey {
                    case enabled
                    case keepLast = "keep_last"
                    case maxAgeDays = "max_age_days"
                    case quotaBytes = "quota_bytes"
                    case setBy = "set_by"
                    case setAt = "set_at"
                }

                public init(from decoder: any Decoder) throws {
                    let container = try decoder.container(keyedBy: CodingKeys.self)
                    self.enabled = try container.decode(Bool.self, forKey: .enabled)
                    self.keepLast = try container.decode(Int64?.self, forKey: .keepLast)
                    self.maxAgeDays = try container.decode(Int64?.self, forKey: .maxAgeDays)
                    self.quotaBytes = try container.decode(Int64?.self, forKey: .quotaBytes)
                    self.setBy = try container.decode(Int64?.self, forKey: .setBy)
                    self.setAt = try container.decode(Int64?.self, forKey: .setAt)
                }

                public func encode(to encoder: any Encoder) throws {
                    var container = encoder.container(keyedBy: CodingKeys.self)
                    try container.encode(self.enabled, forKey: .enabled)
                    try container.encode(self.keepLast, forKey: .keepLast)
                    try container.encode(self.maxAgeDays, forKey: .maxAgeDays)
                    try container.encode(self.quotaBytes, forKey: .quotaBytes)
                    try container.encode(self.setBy, forKey: .setBy)
                    try container.encode(self.setAt, forKey: .setAt)
                }
            }
        }
    }
}
